def _validate_contracts() -> None:
    for capability_id, contract in CAPABILITY_INPUT_CONTRACTS.items():
        if contract.get("capabilityId") != capability_id or contract.get("contractVersion") != CONTRACT_VERSION:
            raise ValueError(f"capability input contract identity drifted: {capability_id}")
        fields = contract.get("fieldDefinitions") or []
        keys = [str(field.get("key") or "") for field in fields]
        if len(keys) != len(set(keys)) or not all(keys):
            raise ValueError(f"capability input field keys are invalid: {capability_id}")
        for field in fields:
            required = {"sourceLabel", "label", "inputType", "valueType", "format", "placeholder", "helpText", "options", "visibleWhen", "enabledWhen", "semanticOwner", "persistenceOwner", "provenance"}
            if not required.issubset(field):
                raise ValueError(f"capability input field metadata is incomplete: {capability_id}/{field.get('key')}")


_validate_contracts()


def get_input_contract(capability_or_label: str) -> dict[str, Any] | None:
    capability_id = capability_or_label if capability_or_label in CAPABILITY_INPUT_CONTRACTS else LABEL_TO_CAPABILITY_ID.get(capability_or_label, "")
    contract = CAPABILITY_INPUT_CONTRACTS.get(capability_id)
    if contract is None:
        return None
    result = deepcopy(contract)
    label = CAPABILITY_DISPLAY_LABELS.get(capability_id, capability_or_label)
    if result.get("inputMode") == "freeform":
        result["usageFormats"] = [str(result.get("entryShape") or f"【{label}】")]
        return result
    usage_formats: list[str] = []
    for variant in result.get("variants") or []:
        facts = [f"输入分支：{variant.get('description') or variant.get('id') or '标准输入'}"]
        if variant.get("requiredFields"):
            facts.append("必填：" + "、".join(variant["requiredFields"]))
        facts.extend("至少一项：" + " / ".join(group) for group in variant.get("requiredAnyOf") or [] if group)
        facts.extend(str(action) for action in variant.get("preActions") or [])
        if variant.get("controlledInputFields"):
            facts.append("发送后粘贴字段：" + "、".join(variant["controlledInputFields"]))
        for field, values in (variant.get("fieldValues") or {}).items():
            facts.append(f"{field}取值：" + " / ".join(values))
        usage_formats.append("；".join(facts))
    result["usageFormats"] = usage_formats or [f"【{label}】"]
    return result
